import * as React from "react";

export type BatteryEmptyIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function BatteryEmptyIcon({ size = 20, ...props }: BatteryEmptyIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3" y="8" width="16" height="8"/><path d="M21 11v2"/>
    </svg>
  );
}
